 return {get inside(){return inside},get mobs(){return keeper&&boneQuest?[...mobs,keeper]:mobs},get boneKeeperDead(){return !!keeper&&keeper.hp<=0},setBoneQuest,ensureGreatBone,drops,blockers,torches,nearTorch,takeTorch,warm,projectileBlocked,can:(x,z)=>free(x,z,.25),free,nearPortal,nearCrypt,nearStoryGrave:()=>inside&&Math.hypot(camera.position.x+330,camera.position.z+174)<3,travel,tick,killed,snapshot,restore,reset(){inside=false;root.visible=false;clearShots();for(const n of mobs)n.aggro=null}};
